import ShopWave from '@shopwave/sdk';

const client = new ShopWave({ apiKey: 'sk_live_abc123' });
const products = await client.products.list({ category: 'electronics', limit: 10 });
console.log(products.data);

import requests

response = requests.get(
    'https://us-east.api.shopwave.example.com/v3/orders',
    headers={'Authorization': f'Bearer {access_token}'},
    params={'status': 'shipped', 'limit': 20}
)
for order in response.json()['data']:
    print(f"Order {order['id']}: {order['status']}")

const order = await client.orders.create({
  items: [{ product_id: 'prod_abc123', variant_id: 'var_s_blk', quantity: 2 }],
  shipping_address: { line1: '123 Main St', city: 'Austin', state: 'TX', postal_code: '78701', country: 'US' },
  payment_method_id: 'pm_visa_4242'
});
console.log(`Order ${order.id}: ${order.status}`);
